    "ask.hello": { zh: "你好！我是 Miiuz，你在马来西亚的旅行助手。可以问我入境、交通、哪家店好吃、门票多少钱，也可以直接说“把第二站换成购物”，我会帮你改行程。", en: "Hi, I'm Miiuz, your travel assistant in Malaysia. Ask me about entry, getting around, where to eat or ticket prices, or say \"swap the second stop for shopping\" and I'll edit your plan.", ko: "안녕하세요! 말레이시아 여행 도우미 Miiuz예요. 입국, 교통, 맛집, 입장료 등을 물어보세요. \"두 번째 장소를 쇼핑으로 바꿔 줘\"라고 하면 일정도 바로 고쳐 드려요.", ja: "こんにちは！マレーシア旅行のアシスタント、Miiuzです。入国、交通、おいしいお店、入場料などを聞いてください。「2か所目を買い物に変えて」と言えば、プランも変更します。" },
    "ask.thinking": { zh: "思考中…", en: "Thinking…", ko: "생각 중…", ja: "考え中…" },
    "ask.searching": { zh: "正在搜索：{q}", en: "Searching: {q}", ko: "검색 중: {q}", ja: "検索中：{q}" },
    "ask.searchingAny": { zh: "正在搜索最新信息…", en: "Searching for current info…", ko: "최신 정보를 검색하는 중…", ja: "最新情報を検索中…" },
    "ask.sources": { zh: "来源", en: "Sources", ko: "출처", ja: "出典" },
    "ask.planUpdated": { zh: "Miiuz 已更新你的行程", en: "Miiuz updated your plan", ko: "Miiuz가 일정을 수정했어요", ja: "Miiuzがプランを更新しました" },
    "ask.viewPlan": { zh: "查看行程", en: "View plan", ko: "일정 보기", ja: "プランを見る" },
    "ask.stopped": { zh: "（已停止）", en: "(stopped)", ko: "(중지됨)", ja: "（停止しました）" },
    "ask.truncated": { zh: "（回答被截断，可以让它说简短些）", en: "(Cut short; try asking for less at once.)", ko: "(답변이 잘렸어요. 질문을 나눠서 해 보세요.)", ja: "（回答が途中で切れました。質問を分けてみてください）" },
    "ask.tooLong": { zh: "这段对话已经很长了，点“新对话”重新开始吧。", en: "This chat is getting long. Start a new chat to keep going.", ko: "대화가 길어졌어요. '새 대화'로 다시 시작해 주세요.", ja: "会話が長くなりました。「新しい会話」で始め直してください。" },
    "ask.err.rate": { zh: "请求太频繁了，等一会再问。", en: "Too many requests. Wait a moment and try again.", ko: "요청이 너무 많아요. 잠시 후 다시 시도하세요.", ja: "リクエストが多すぎます。少し待ってからお試しください。" },
    "ask.err.session": { zh: "登录已过期，请重新登录 Claude。", en: "Your Claude session expired; sign in again.", ko: "Claude 로그인이 만료됐어요. 다시 로그인하세요.", ja: "Claudeのログインが切れました。再度ログインしてください。" },
    "ask.err.refused": { zh: "这个问题我没法回答，换个问法试试。", en: "I can't help with that one. Try asking differently.", ko: "이 질문에는 답할 수 없어요. 다르게 물어봐 주세요.", ja: "この質問にはお答えできません。別の聞き方をお試しください。" },
    "ask.err.off": { zh: "问 Miiuz 暂时用不了。", en: "Ask Miiuz isn't available right now.", ko: "지금은 Miiuz에게 물어볼 수 없어요.", ja: "「Miiuzに聞く」は現在ご利用いただけません。" },
    "ask.err.network": { zh: "连接出了点问题，检查网络后再试一次。", en: "Connection problem. Check your network and try again.", ko: "연결에 문제가 있어요. 네트워크를 확인하고 다시 시도하세요.", ja: "接続に問題があります。通信状況を確認して再度お試しください。" },
    "ask.err.generic": { zh: "出了点问题，稍后再试一次。", en: "Something went wrong. Please try again shortly.", ko: "문제가 생겼어요. 잠시 후 다시 시도하세요.", ja: "問題が発生しました。しばらくしてからお試しください。" },
    "ask.footServer": { zh: "Miiuz 会联网查最新信息并附上来源。价格和营业时间以官方为准。", en: "Miiuz searches the web for current info and cites sources. Confirm prices and hours with official sites.", ko: "Miiuz는 웹에서 최신 정보를 찾아 출처와 함께 알려 줘요. 가격과 영업시간은 공식 정보를 확인하세요.", ja: "Miiuzはウェブで最新情報を調べ、出典付きで答えます。料金や営業時間は公式情報をご確認ください。" },
    "ask.footArtifact": { zh: "这个预览里 Miiuz 根据旅行知识回答，不能联网搜索。价格和营业时间以官方为准。", en: "In this preview Miiuz answers from travel knowledge and can't search the web. Confirm prices and hours officially.", ko: "이 미리보기에서는 웹 검색 없이 여행 지식으로 답해요. 가격과 영업시간은 공식 정보를 확인하세요.", ja: "このプレビューではウェブ検索をせず、旅行知識で回答します。料金や営業時間は公式情報をご確認ください。" },
    "ask.footOff": { zh: "问 Miiuz 暂时用不了，App 的其他功能都能正常使用。", en: "Ask Miiuz isn't available right now. Everything else in the app works as usual.", ko: "지금은 Miiuz에게 물어볼 수 없어요. 앱의 다른 기능은 모두 정상이에요.", ja: "「Miiuzに聞く」は現在ご利用いただけません。アプリのほかの機能は通常どおり使えます。" },
    "ask.suggest": {
      zh: ["我不吃辣，晚饭吃什么？", "下大雨了，帮我改成室内路线", "想买白咖啡和榴莲干当手信，顺路去哪？", "Grab 去机场大概多少钱？"],
      en: ["I can't eat spicy food. What should I have for dinner?", "It's pouring. Switch my route to indoor places.", "Where can I buy white coffee and durian snacks on my route?", "Roughly how much is a Grab to the airport?"],
      ko: ["매운 걸 못 먹어요. 저녁은 뭘 먹을까요?", "비가 많이 와요. 실내 위주로 일정을 바꿔 주세요.", "화이트 커피랑 두리안 과자를 사고 싶어요. 동선상 어디가 좋아요?", "공항까지 Grab 요금은 대략 얼마예요?"],
      ja: ["辛いものが苦手です。夕食は何がおすすめ？", "大雨です。屋内中心のルートに変えてください。", "ホワイトコーヒーとドリアンのお菓子を買いたい。ルート上でどこがいい？", "空港までGrabだといくらくらい？"],
    },

