    "member.join": { zh: "免费加入", en: "Join free", ko: "무료 가입", ja: "無料で登録" },
    "member.title": { zh: "加入 Miiuz BB 会员", en: "Join Miiuz BB", ko: "Miiuz BB 회원 가입", ja: "Miiuz BB メンバー登録" },
    "member.lead": { zh: "会员免费。不注册也能一直使用，加入会员享更多好处。", en: "Membership is free. You can keep using the app as a guest; members get extra.", ko: "회원 가입은 무료예요. 게스트로도 계속 쓸 수 있지만, 회원은 혜택이 더 많아요.", ja: "登録は無料。ゲストのままでも使えますが、メンバーには特典があります。" },
    "member.perk.signup": { zh: "加入即得 10 积分", en: "+10 points when you join", ko: "가입하면 10포인트", ja: "登録で10ポイント" },
    "member.perk.invite": { zh: "每邀请一位朋友加入，再得 10 积分", en: "+10 points for every friend who joins with your link", ko: "내 링크로 친구가 가입할 때마다 10포인트", ja: "招待した友だちが登録するたびに10ポイント" },
    "member.perk.offers": { zh: "会员专享小礼物和优惠", en: "Member-only goodies and offers", ko: "회원 전용 선물과 혜택", ja: "メンバー限定のプレゼントと特典" },
    "member.perk.news": { zh: "最新旅行资讯和动态", en: "Latest travel news and updates", ko: "최신 여행 소식과 업데이트", ja: "最新の旅行ニュースとお知らせ" },
    "member.tiers": { zh: "会员等级", en: "Member tiers", ko: "회원 등급", ja: "メンバーランク" },
    "member.tierNote": { zh: "按累计获得的积分升级，等级和积分永不过期。", en: "Tiers go by points ever earned. Tiers and points never expire.", ko: "누적 적립 포인트로 등급이 올라가요. 등급과 포인트는 만료되지 않아요.", ja: "これまでに獲得したポイントでランクが上がります。ランクとポイントに有効期限はありません。" },
    "member.invited": { zh: "朋友邀请了你：加入后你们俩各得 10 积分。", en: "A friend invited you: you'll both get 10 points when you join.", ko: "친구가 초대했어요. 가입하면 두 분 모두 10포인트를 받아요.", ja: "友だちからの招待です。登録すると2人とも10ポイントもらえます。" },
