    "member.email": { zh: "邮箱", en: "Email", ko: "이메일", ja: "メールアドレス" },
    "member.marketing": { zh: "给我发送会员优惠、小礼物和旅行资讯", en: "Email me member offers, goodies and travel news", ko: "회원 혜택, 선물, 여행 소식을 이메일로 받을게요", ja: "メンバー特典・プレゼント・旅行ニュースをメールで受け取る" },
    "member.consent": { zh: "加入即表示你同意 Miiuz Beyond Borders Sdn. Bhd. 保存你的邮箱、姓名、国籍以及你填写的电话和紧急联系人，用于会员服务和紧急情况。你可以随时修改或删除。", en: "By joining, you agree that Miiuz Beyond Borders Sdn. Bhd. keeps your email, name, nationality and any phone number or emergency contact you add, to run your membership and help you in an emergency. You can change or remove them anytime.", ko: "가입하면 Miiuz Beyond Borders Sdn. Bhd.가 회원 서비스와 긴급 상황 지원을 위해 이메일, 이름, 국적, 입력한 전화번호와 비상 연락처를 보관하는 데 동의하는 거예요. 언제든 수정하거나 삭제할 수 있어요.", ja: "登録すると、Miiuz Beyond Borders Sdn. Bhd.が会員サービスと緊急時のサポートのために、メールアドレス・氏名・国籍と、入力された電話番号・緊急連絡先を保管することに同意したことになります。いつでも変更・削除できます。" },
    "member.send": { zh: "发送验证码", en: "Send my code", ko: "인증 코드 받기", ja: "認証コードを送る" },
