    "member.off": { zh: "会员功能即将开放。其他功能都可以免费使用。", en: "Membership opens soon. Everything else in the app is free to use.", ko: "회원 기능은 곧 열려요. 다른 기능은 모두 무료로 쓸 수 있어요.", ja: "メンバー機能はまもなく公開。その他の機能は無料で使えます。" },
    "member.setupMissing": { zh: "会员数据库还没设置好，请联系管理员。", en: "The membership database isn't set up yet. Please contact the app owner.", ko: "회원 데이터베이스가 아직 설정되지 않았어요. 앱 운영자에게 문의하세요.", ja: "メンバー用データベースがまだ設定されていません。運営者にお問い合わせください。" },
    "member.welcome": { zh: "欢迎加入 Miiuz BB！+10 积分", en: "Welcome to Miiuz BB! +10 points", ko: "Miiuz BB에 오신 걸 환영해요! +10포인트", ja: "Miiuz BBへようこそ！+10ポイント" },
